/**
 * AI coach use case (task 21.1).
 *
 * `askCoach(userId, request, deps)` answers a member's training
 * question with structured advice generated by a language model through
 * the Vercel AI SDK. Every collaborator is injected:
 *
 *   - `model`    — any AI SDK `LanguageModel`. Production passes the
 *                  Mistral provider; tests pass the SDK mock model, so
 *                  nothing reaches the network.
 *   - `sessions` — the `ProgressionRepo` port of `@athlya/members`, read
 *                  once for the last 30 days.
 *   - `consents` — the member's `thirdParty` opt-in. Without it the
 *                  request is refused before any data is read.
 *   - `quota`    — a per-user daily counter (UTC day). A store failure
 *                  fails closed: no model call without a counted quota.
 *
 * Flow: consent → quota → read sessions → minimised context → model →
 * `CoachAdviceSchema` validation. The quota is consumed before the
 * model call, so a request that fails upstream still counts; this keeps
 * a member from bypassing the quota by forcing provider errors.
 *
 * Nothing is persisted besides the quota counter: neither the question
 * nor the advice is stored.
 */

import { progressionWindowBounds } from '@athlya/members/progression';
import { CoachAdviceSchema } from '@athlya/shared/schemas/api';
import { generateText, Output } from 'ai';

import { buildCoachContext, COACH_CONTEXT_DAYS } from './context.js';
import { CoachError } from './errors.js';
import { buildCoachPrompt } from './prompt.js';

import type { ProgressionRepo } from '@athlya/members/progression';
import type {
  CoachAdvice,
  CoachAskResponse,
  CoachLocale,
  CoachQuota,
} from '@athlya/shared/schemas/api';
import type { LanguageModel } from 'ai';

/** Requests per member and UTC day when the deployment sets none. */
export const DEFAULT_COACH_DAILY_LIMIT = 10;

/** Most session rows read for the context window. */
export const COACH_SESSION_READ_LIMIT = 200;

/** Upper bound on one model call, retries included. */
export const COACH_MODEL_TIMEOUT_MS = 20_000;

/** Output token budget of one answer. */
export const COACH_MAX_OUTPUT_TOKENS = 1_000;

const DAY_MS = 24 * 60 * 60 * 1000;

/** Language model accepted by the coach (AI SDK `LanguageModel`). */
export type CoachModel = LanguageModel;

/** Per-user daily counter. */
export interface CoachQuotaStore {
  /**
   * Add one request to `userId`'s counter for `day` (`YYYY-MM-DD`, UTC)
   * and return the count after the increment. The counter must expire
   * after `ttlSec` seconds.
   */
  increment(userId: string, day: string, ttlSec: number): Promise<number>;
  /** Current count of `userId` for `day`, 0 when unset. */
  peek(userId: string, day: string): Promise<number>;
}

/** Member consent lookup. */
export interface CoachConsentReader {
  /** True when the member accepts sharing data with third parties. */
  hasThirdPartyConsent(userId: string): Promise<boolean>;
}

export interface CoachQuotaDeps {
  readonly quota: CoachQuotaStore;
  /** Defaults to {@link DEFAULT_COACH_DAILY_LIMIT}. */
  readonly dailyLimit?: number;
  /** Defaults to `Date.now`. */
  readonly now?: () => number;
}

export interface AskCoachDeps extends CoachQuotaDeps {
  readonly model: CoachModel;
  readonly sessions: ProgressionRepo;
  readonly consents: CoachConsentReader;
  /** Defaults to {@link COACH_MODEL_TIMEOUT_MS}. */
  readonly timeoutMs?: number;
}

export interface AskCoachRequest {
  readonly question: string;
  readonly locale: CoachLocale;
}

interface QuotaWindow {
  readonly day: string;
  readonly resetsAtMs: number;
}

function quotaWindow(nowMs: number): QuotaWindow {
  const start = Math.floor(nowMs / DAY_MS) * DAY_MS;
  return { day: new Date(start).toISOString().slice(0, 10), resetsAtMs: start + DAY_MS };
}

function dailyLimitOf(deps: CoachQuotaDeps): number {
  const limit = deps.dailyLimit ?? DEFAULT_COACH_DAILY_LIMIT;
  return Number.isInteger(limit) && limit > 0 ? limit : DEFAULT_COACH_DAILY_LIMIT;
}

function quotaView(limit: number, used: number, window: QuotaWindow): CoachQuota {
  return {
    limit,
    remaining: Math.max(0, limit - used),
    resetsAt: new Date(window.resetsAtMs).toISOString(),
  };
}

/** Daily quota of `userId` without consuming it. */
export async function getCoachQuota(userId: string, deps: CoachQuotaDeps): Promise<CoachQuota> {
  const now = (deps.now ?? Date.now)();
  const window = quotaWindow(now);
  const limit = dailyLimitOf(deps);
  let used: number;
  try {
    used = await deps.quota.peek(userId, window.day);
  } catch (err) {
    throw new CoachError('quota_unavailable', 'coach quota store unavailable', { cause: err });
  }
  return quotaView(limit, used, window);
}

/**
 * Answer `request.question` for `userId`.
 *
 * Throws {@link CoachError}: `consent_required`, `quota_exceeded` (with
 * `retryAfterSec` until the next UTC midnight), `quota_unavailable`,
 * `upstream_failed` or `invalid_output`.
 */
export async function askCoach(
  userId: string,
  request: AskCoachRequest,
  deps: AskCoachDeps,
): Promise<CoachAskResponse> {
  if (!(await deps.consents.hasThirdPartyConsent(userId))) {
    throw new CoachError('consent_required', 'third-party data sharing consent is required');
  }

  const now = (deps.now ?? Date.now)();
  const window = quotaWindow(now);
  const limit = dailyLimitOf(deps);
  const ttlSec = Math.ceil((window.resetsAtMs - now) / 1000);
  let used: number;
  try {
    used = await deps.quota.increment(userId, window.day, Math.max(1, ttlSec));
  } catch (err) {
    throw new CoachError('quota_unavailable', 'coach quota store unavailable', { cause: err });
  }
  if (used > limit) {
    throw new CoachError('quota_exceeded', 'daily coach quota exceeded', {
      retryAfterSec: Math.max(1, ttlSec),
    });
  }

  const bounds = progressionWindowBounds(COACH_CONTEXT_DAYS, now);
  const rows = await deps.sessions.listInWindow(userId, {
    ...bounds,
    limit: COACH_SESSION_READ_LIMIT,
  });
  const { system, prompt } = buildCoachPrompt(
    buildCoachContext(rows, now),
    request.question,
    request.locale,
  );

  let raw: unknown;
  try {
    const result = await generateText({
      model: deps.model,
      system,
      prompt,
      output: Output.object({ schema: CoachAdviceSchema }),
      temperature: 0.3,
      maxOutputTokens: COACH_MAX_OUTPUT_TOKENS,
      maxRetries: 1,
      abortSignal: AbortSignal.timeout(deps.timeoutMs ?? COACH_MODEL_TIMEOUT_MS),
    });
    raw = result.output;
  } catch (err) {
    if (isOutputError(err)) {
      throw new CoachError('invalid_output', 'model output does not match the advice schema', {
        cause: err,
      });
    }
    throw new CoachError('upstream_failed', 'model provider call failed', { cause: err });
  }

  const parsed = CoachAdviceSchema.safeParse(raw);
  if (!parsed.success) {
    throw new CoachError('invalid_output', 'model output does not match the advice schema');
  }
  const advice: CoachAdvice = parsed.data;

  return {
    advice,
    quota: quotaView(limit, used, window),
    generatedAt: new Date(now).toISOString(),
  };
}

/** AI SDK errors raised when the model answered but not with valid output. */
function isOutputError(err: unknown): boolean {
  const name = typeof err === 'object' && err !== null ? (err as { name?: unknown }).name : '';
  return (
    name === 'AI_NoObjectGeneratedError' ||
    name === 'AI_NoOutputGeneratedError' ||
    name === 'AI_TypeValidationError' ||
    name === 'AI_JSONParseError'
  );
}
